  cuda un-fused = [-0.1295, -0.1176, -0.1527, -0.1343, -0.1688]
  cuda fused    = [-0.1295, -0.0072, -0.1736, -0.0097, -0.0124]   <-- wrong for rows > 0
  cuda fused/row= [-0.1295, -0.1175, -0.1526, -0.1343, -0.1688]
