    conv3: Conv2d<B>,
    conv4: Conv2d<B>,
    head: Conv2d<B>,
    pool: Pool2d,
}

impl<B: Backend> ConvNet<B> {
    fn new(device: &B::Device) -> Self {
        let conv1 = Conv2dConfig::new([3, 32], [3, 3])
            .with_padding(PaddingConfig2d::Same)
            .init(device);
        let conv2 = Conv2dConfig::new([32, 64], [3, 3])
            .with_padding(PaddingConfig2d::Same)
            .init(device);
        let conv3 = Conv2dConfig::new([64, 128], [3, 3])
            .with_padding(PaddingConfig2d::Same)
            .init(device);
        let conv4 = Conv2dConfig::new([128, 128], [3, 3])
            .with_padding(PaddingConfig2d::Same)
            .init(device);
        let head = Conv2dConfig::new([128, 1], [1, 1]).init(device);
        let pool = Pool2dConfig::new([2, 2]).init();

        Self {
            conv1,
            conv2,
            conv3,
            conv4,
            head,
            pool,
        }
    }

    fn forward(&self, input: Tensor<B, 4>) -> Tensor<B, 3> {
        let x = self.pool.forward(relu(self.conv1.forward(input)));
        let x = self.pool.forward(relu(self.conv2.forward(x)));
        let x = self.pool.forward(relu(self.conv3.forward(x)));
        let x = self.pool.forward(relu(self.conv4.forward(x)));
        let x = sigmoid(self.head.forward(x));
        x.squeeze_dim::<3>(1)
    }
}

fn main() {
    let device = LibTorchDevice::Mps;
    let mut model = ConvNet::<MyBackend>::new(&device);
    let mut optimizer = AdamConfig::new().init();
    let criterion = MseLoss::new();
    let input = Tensor::<MyBackend, 4>::zeros([BATCH_SIZE, 3, INPUT_SIZE, INPUT_SIZE], &device);
    let target = Tensor::<MyBackend, 3>::zeros([BATCH_SIZE, GRID_SIZE, GRID_SIZE], &device);

    println!("Using device: {:?}", device);
    println!("Trainable parameters: {}", model.num_params());

    for _ in 0..WARMUP_STEPS {
        let preds = model.forward(input.clone());
        let loss = criterion.forward(preds, target.clone(), Reduction::Mean);
        let grads = loss.backward();
        let grads = GradientsParams::from_grads(grads, &model);
        model = optimizer.step(LEARNING_RATE, model, grads);
    }

    let start = Instant::now();
    for _ in 0..MEASURE_STEPS {
        let preds = model.forward(input.clone());
        let loss = criterion.forward(preds, target.clone(), Reduction::Mean);
        let grads = loss.backward();
        let grads = GradientsParams::from_grads(grads, &model);
        model = optimizer.step(LEARNING_RATE, model, grads);
    }

    let total_ms = start.elapsed().as_secs_f64() * 1000.0;
    println!("Measured {} training steps, avg: {:.2} ms", MEASURE_STEPS, total_ms / MEASURE_STEPS as f64);
}
```

