        Distribution::Uniform(-1., 1.),
        &Default::default(),
    );
    // Broadcast bool mask: [1, 1, seq_len, seq_len], shared across all batches and heads.
    let mask = TestTensor::<4>::random(
        [1, 1, seq_len, seq_len],
        Distribution::Uniform(0., 1.),
        &Default::default(),
    )
    .greater_elem(0.7);

